-- DriveHub GH: import 20 customer testimonials for staff moderation.
-- Safe to re-run: stable IDs + INSERT OR IGNORE prevent duplicate rows.
-- All imported reviews are PENDING. Nothing is publicly published until staff approve it.
-- Source: DriveHub_GH_Testimonials_Final.docx
INSERT OR IGNORE INTO reviews
  (id, customer_name, customer_email, rating, what_went_well, what_to_improve, status, submitted_at)
VALUES
  ('DHG-TESTIMONIAL-2026-01', 'Kwabena Agyeman-Duah, Kumasi, Ashanti Region', NULL, 5, 'I booked the Toyota RAV4 from DriveHub GH for a week of client visits around Kumasi and Ejisu. It started every morning without fuss, the cabin stayed cool, and the fuel economy surprised me. By the end of the week I did not want to hand it back.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-02', 'Ama Essuman, Takoradi, Western Region', NULL, 5, 'I needed a vehicle for a full month while working on a project at the port, and DriveHub GH made it simple. The Outlander was clean on day one and just as reliable on day thirty. No breakdowns, no stress, just a car I could depend on.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-03', 'Emmanuel Tetteh, Tema, Greater Accra Region', NULL, 5, 'Our firm has rented a Santa Fe from DriveHub GH on a long-term basis for over six months now. Servicing is handled on time, the paperwork is clear, and the car looks as good today as when we collected it. It has been far easier than owning and maintaining our own vehicle.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-04', 'Alhassan Iddrisu, Tamale, Northern Region', NULL, 5, 'I spent a month travelling between communities for fieldwork, and the Prado never let me down. Long hours behind the wheel, dusty roads, hot afternoons, and it kept going comfortably. Renting monthly with DriveHub GH was the best decision for this assignment.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-05', 'Selorm Agbenyega, Ho, Volta Region', NULL, 5, 'My family came home for a week-long visit and we needed room for everyone. The CR-V handled airport runs, church, market trips and a day out to Hohoe without a single problem. It felt like our own car for the week.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-06', 'Mavis Appiah-Kubi, Sunyani, Bono Region', NULL, 5, 'The 7-seater Outlander was perfect for our family of six. Everyone had room, the kids were comfortable on the long drive, and there was still space for the luggage. For the quality of the car, DriveHub GH gave us excellent value.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-07', 'Priscilla Nartey, Spintex, Greater Accra Region', NULL, 5, 'I wanted something refined for a week of business meetings, and the Acura MDX delivered. The ride is smooth, the seats are superb, and I arrived at every appointment feeling fresh. It is rare to get this level of comfort from a rental.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-08', 'Yaw Frimpong, Koforidua, Eastern Region', NULL, 5, 'I was not sure what to expect, but the Honda CR-V from DriveHub GH was a pleasant surprise. Practical, comfortable and economical on fuel, it covered everything I needed. I got far more than I paid for.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-09', 'Nii Armah Quaye, Teshie, Greater Accra Region', NULL, 5, 'We rented the Land Cruiser V8 for my brother''s wedding weekend, and it turned heads everywhere we went. It was spotless, powerful and extremely comfortable. DriveHub GH helped make our family''s big day even more special.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-10', 'Rukaya Mohammed, Wa, Upper West Region', NULL, 5, 'I drove the Hyundai Santa Fe from Wa to Kumasi and back, and I barely felt the distance. The seats were comfortable, the air conditioning was excellent, and the car stayed steady the whole way. I would happily book it again.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-11', 'Atuguba Akolgo, Bolgatanga, Upper East Region', NULL, 5, 'The road to the border communities near Paga is not kind to vehicles, but the Prado took it in its stride. No rattles, no warning lights, and no worries. These are cars built for real Ghanaian roads, and DriveHub GH keeps them in top shape.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-12', 'Gifty Nyarko, Obuasi, Ashanti Region', NULL, 5, 'I rented the RAV4 in the middle of the rainy season, with flooded stretches and plenty of potholes on the way. The car stayed composed and confident throughout. I have rented from other places before and none felt this solid.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-13', 'Kofi Sarpong, Tarkwa, Western Region', NULL, 5, 'Our site visits around Tarkwa involve rough, uneven tracks, and the Land Cruiser V8 handled all of it. It is powerful, sturdy and still comfortable inside. DriveHub GH clearly looks after its vehicles properly.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-14', 'Edem Dzifa Kpodo, Hohoe, Volta Region', NULL, 5, 'We took the Outlander up the hilly road toward Wli Falls and it climbed without complaint. Steady on the bends, firm on the rough patches, and comfortable for the whole group. A great car for exploring the Volta Region.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-15', 'Nana Akua Serwaa, Techiman, Bono East Region', NULL, 5, 'I had a question late in the evening and someone from DriveHub GH replied quickly and politely. When I needed a small adjustment to my booking, it was sorted without any drama. Support like this is what keeps me coming back.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-16', 'Barrister Kwesi Hammond, Cape Coast, Central Region', NULL, 5, 'I asked for a driver for a court week and the experience was excellent. He was punctual, courteous, and knew the routes well, and he drove smoothly and safely throughout. It allowed me to prepare my cases in the back seat in complete comfort.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-17', 'Comfort Ayisi, Winneba, Central Region', NULL, 5, 'Every car I have collected from DriveHub GH has been spotless inside and out, with everything working properly. You can tell the vehicles are checked and cared for before they reach the customer. That attention to detail builds real trust.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-18', 'Joseph Nkrumah, Sekondi, Western Region', NULL, 5, 'I found the cars on the DriveHub GH website, chose the one I liked and sent an enquiry. The team got back to me quickly and the pickup was smooth. Booking a rental has never been this straightforward.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-19', 'Ibrahim Salifu, Damongo, Savannah Region', NULL, 5, 'We rent from DriveHub GH for our team''s field trips across the Savannah Region. The vehicles are dependable, the team is professional, and they respond fast whenever we need to adjust our plans. They understand what organisations need from a rental partner.', NULL, 'pending', CURRENT_TIMESTAMP),
  ('DHG-TESTIMONIAL-2026-20', 'Esi Quansah, Kasoa, Central Region', NULL, 5, 'Great cars, honest people, no stress. Highly recommended.', NULL, 'pending', CURRENT_TIMESTAMP);

-- Verification: should return 20 rows for this import batch.
SELECT status, COUNT(*) AS review_count
FROM reviews
WHERE id LIKE 'DHG-TESTIMONIAL-2026-%'
GROUP BY status;
